import type { ClassId } from "./macros";

/**
 * Every ability in each class's WoW Forever spellbook (client build of Oct 22, plus the Oct 26 patch),
 * including talent-granted ones, whose description starts with "Talent (Tree, N points)".
 * Pet abilities and items the macros use are kept at the end of a class's list.
 * Icons load from Wowhead's icon CDN by name; a missing icon falls back to a glyph.
 * Tooltip text is rank-free on purpose: numbers change every rank and every patch.
 */
export type Ability = {
  name: string;
  icon: string;
  /** Cast type, cooldown, range, requirements: one short line. */
  meta: string;
  desc: string;
};

type Row = [name: string, icon: string, meta: string, desc: string];

