const BY_CLASS = Object.fromEntries(
  Object.entries(DATA).map(([c, rows]) => [
    c,
    new Map(rows.map(([name, icon, meta, desc]) => [name.toLowerCase(), { name, icon, meta, desc }])),
  ]),
) as Record<ClassId, Map<string, Ability>>;

export function abilitiesFor(classId: ClassId): Ability[] {
  return [...BY_CLASS[classId].values()];
}

export function findAbility(classId: ClassId, name: string): Ability | undefined {
  return BY_CLASS[classId].get(name.toLowerCase());
}

/** Spell names a macro line casts: /cast, /castsequence, /use and #showtooltip, conditionals stripped. */
export function spellsInLine(code: string): string[] {
  const m = code.match(/^(?:#showtooltip|\/cast|\/castsequence|\/use)\s*(.*)$/i);
  if (!m) return [];
  const out: string[] = [];
  for (let part of m[1].split(";")) {
    part = part.replace(/\[[^\]]*\]/g, "").replace(/^\s*reset=\S+\s*/, "").trim();
    for (let s of part.split(",")) {
      s = s.replace(/^!/, "").replace(/\(.*\)$/, "").trim();
      if (s && !/^\d+$/.test(s)) out.push(s);
    }
  }
  return out;
}

